function nthRoot(x, n){
  if(x < 0 || n < 1) return NaN;
  if(n === 1) return x;
  if(x === 0) return 0;
  var g = x;
  for(var i=0;i<200;i++){
    var ng = ((n-1)*g + x/Math.pow(g, n-1)) / n;
    if(Math.abs(ng - g) < 1e-12) { g = ng; break; }
    g = ng;
  }
  return g;
}
function sqrt(x){ return Math.sqrt(x); }
function cbrt(x){ return Math.cbrt(x); }
var EXPORTS = { nthRoot:nthRoot, sqrt:sqrt, cbrt:cbrt };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NthRootForgePure = EXPORTS; }
